(7006675, 1060322, 124982, '<td valign="top">Such an intriguing image! Who is this boy/girl, and where are they running to? Fascinating and thought-provoking!</td>', 'Such an intriguing image! Who is this boy/girl, and where are they running to? Fascinating and thought-provoking!', '2013-03-25 20:55:39.000000', NULL, 1),
