(7006677, 1060359, 8759, '<td valign="top">Good colors, nice contrast. Could be sharper but might be the limitation of the equipment. Somehow looks like a crop from a larger image.</td>', 'Good colors, nice contrast. Could be sharper but might be the limitation of the equipment. Somehow looks like a crop from a larger image.', '2013-03-25 20:57:40.000000', NULL, 1),
(7006678, 1059914, 8759, '<td valign="top">Ready for stock or printing as a motivational poster. I have to say I would never have thought of something like this... Beautiful tribute.</td>', 'Ready for stock or printing as a motivational poster. I have to say I would never have thought of something like this... Beautiful tribute.', '2013-03-25 21:00:26.000000', NULL, 1),
