(7006680, 1059830, 8759, '<td valign="top">Nice, crisp red and a bit sad. God rest her in peace.</td>', 'Nice, crisp red and a bit sad. God rest her in peace.', '2013-03-25 21:04:28.000000', NULL, 1),
(7006681, 1059609, 124982, '<td valign="top">Is this an <img alt="'' . substr(''//www.dpchallenge.com/images/user_icon/21_F.gif'', strrpos(''//www.dpchallenge.com/images/user_icon/21_F.gif'', ''/'') + 1) . ''" border="0" src="//www.dpchallenge.com/images/user_icon/21_F.gif"/> <a href="//www.dpchallenge.com/profile.php?USER_ID=123833" rel="nofollow" target="_blank">mnet</a> image? Regardless of who the author is, this is one of the most beautiful photo''s I''ve seen on DPC in a long time. This just speaks to me in such a deep way. I love the conflict between the storm out at sea and the smooth, calmness of the water by the chair. I would give many a dollar to have been sitting in that chair watching the storm -- one of my favourite activities. I digress, you have a masterpiece here...and one of the very, very few I have ever given a 10 (and a favourite) for.</td>', 'Is this an  mnet image? Regardless of who the author is, this is one of the most beautiful photo''s I''ve seen on DPC in a long time. This just speaks to me in such a deep way. I love the conflict between the storm out at sea and the smooth, calmness of the water by the chair. I would give many a dollar to have been sitting in that chair watching the storm -- one of my favourite activities. I digress, you have a masterpiece here...and one of the very, very few I have ever given a 10 (and a favourite) for.', '2013-03-25 21:05:01.000000', NULL, 1),
(7006682, 1060201, 124982, '<td valign="top">Peaceful, calm...and angelic. Lovely!</td>', 'Peaceful, calm...and angelic. Lovely!', '2013-03-25 21:05:18.000000', NULL, 1),
