(7006751, 1060298, 124982, '<td valign="top">A lovely arrangement. Flowers are lit wonderfully and the thin DoF makes for a great composition. Simple and elegant!</td>', 'A lovely arrangement. Flowers are lit wonderfully and the thin DoF makes for a great composition. Simple and elegant!', '2013-03-25 21:54:18.000000', NULL, 1),
(7006752, 1059471, 124982, '<td valign="top">Well captured! Not sure how you managed to get so much detail in the feathers of this critter! Wonderfully sharp.</td>', 'Well captured! Not sure how you managed to get so much detail in the feathers of this critter! Wonderfully sharp.', '2013-03-25 21:54:54.000000', NULL, 1),
