(7009846, 1059914, 94815, '<td valign="top">There''s something about this, maybe my ignorance, but something that is not the appearance of Shez but the spirit of Shez. It''s as of Shez might have wanted to express her philosophy of life. So sadly missed but her community carries her spirit on.</td>', 'There''s something about this, maybe my ignorance, but something that is not the appearance of Shez but the spirit of Shez. It''s as of Shez might have wanted to express her philosophy of life. So sadly missed but her community carries her spirit on.', '2013-03-30 22:13:59.000000', NULL, 1),
(7009896, 1060362, 94815, '<td valign="top">Beautifully shot and processed. There''s etherial quality in the slightly muted colors and strong blacks beyond nature into another realm - as we can hope is the case for Shez.</td>', 'Beautifully shot and processed. There''s etherial quality in the slightly muted colors and strong blacks beyond nature into another realm - as we can hope is the case for Shez.', '2013-03-31 00:07:12.000000', NULL, 1),
(7009897, 1058859, 94815, '<td valign="top">Syrikingly executed ala Shez. One of the best in the challenge. Voted earlier.</td>', 'Syrikingly executed ala Shez. One of the best in the challenge. Voted earlier.', '2013-03-31 00:08:26.000000', NULL, 1),
(7009898, 1059866, 94815, '<td valign="top">Would love to know about your technique. A lot more. One of the best. Already voted.</td>', 'Would love to know about your technique. A lot more. One of the best. Already voted.', '2013-03-31 00:09:56.000000', NULL, 1),
(7009899, 1059998, 94815, '<td valign="top">Lovely flower so well executed in the Shez way.</td>', 'Lovely flower so well executed in the Shez way.', '2013-03-31 00:11:02.000000', NULL, 1),
(7009900, 1059876, 94815, '<td valign="top">Well done in a Shez style. Nice tribute.</td>', 'Well done in a Shez style. Nice tribute.', '2013-03-31 00:12:18.000000', NULL, 1),
(7009902, 1058774, 63218, '<td valign="top">I see it!</td>', 'I see it!', '2013-03-31 00:24:24.000000', NULL, 1),
(7009915, 1058859, 101668, '<td valign="top">Superb clarity and composition. An excellent tribute to Shez</td>', 'Superb clarity and composition. An excellent tribute to Shez', '2013-03-31 04:37:41.000000', NULL, 1),
(7009916, 1060149, 101668, '<td valign="top">Colourful just as Shez liked it.</td>', 'Colourful just as Shez liked it.', '2013-03-31 04:39:45.000000', NULL, 1),
(7009917, 1060205, 101668, '<td valign="top">This is beautiful and a very nice tribute.</td>', 'This is beautiful and a very nice tribute.', '2013-03-31 05:17:53.000000', NULL, 1),
(7009918, 1059915, 101668, '<td valign="top">So true and lovely entry great tribute. Let''s not forget her</td>', 'So true and lovely entry great tribute. Let''s not forget her', '2013-03-31 05:19:30.000000', NULL, 1),
(7009921, 1057766, 101668, '<td valign="top">Oh wow, lovey picture, lovely entry. Just love the light and clarity of the water drops. Beautiful</td>', 'Oh wow, lovey picture, lovely entry. Just love the light and clarity of the water drops. Beautiful', '2013-03-31 05:28:37.000000', NULL, 1),
(7009922, 1058967, 101668, '<td valign="top">Simply beautiful and an excellent tribute. Love this</td>', 'Simply beautiful and an excellent tribute. Love this', '2013-03-31 05:29:27.000000', NULL, 1),
(7009923, 1058737, 101668, '<td valign="top">Very nice and with pictures such as this she''ll always be in our midst</td>', 'Very nice and with pictures such as this she''ll always be in our midst', '2013-03-31 05:41:53.000000', NULL, 1),
(7009924, 1057796, 101668, '<td valign="top">Great picture, title ? but worthy tribute as well. Love the pp</td>', 'Great picture, title ? but worthy tribute as well. Love the pp', '2013-03-31 05:43:09.000000', NULL, 1),
(7009989, 1059203, 100831, '<td valign="top">A welcome diversion from the garden. Very well executed - I think Shez would have enjoyed your message.</td>', 'A welcome diversion from the garden. Very well executed - I think Shez would have enjoyed your message.', '2013-03-31 10:20:50.000000', NULL, 1),
(7009995, 1059514, 63218, '<td valign="top">This is unusual &amp; interesting.</td>', 'This is unusual & interesting.', '2013-03-31 10:49:52.000000', NULL, 1),
(7009996, 1058908, 63218, '<td valign="top">Well done, the touch of sunlight is perfect.</td>', 'Well done, the touch of sunlight is perfect.', '2013-03-31 10:52:59.000000', NULL, 1),
(7009997, 1060365, 63218, '<td valign="top">Splendid reds here, well done.</td>', 'Splendid reds here, well done.', '2013-03-31 10:56:09.000000', NULL, 1),
(7009998, 1060283, 63218, '<td valign="top">This all goes together very well. Well done.</td>', 'This all goes together very well. Well done.', '2013-03-31 11:01:33.000000', NULL, 1),
(7010000, 1058908, 100831, '<td valign="top">A perfect Shez. Love the light and how you chose the border to match the edges of the leaves.</td>', 'A perfect Shez. Love the light and how you chose the border to match the edges of the leaves.', '2013-03-31 11:04:51.000000', NULL, 1),
(7010001, 1059697, 100831, '<td valign="top">The perfect resting spot. I love how this radiates light. Shez would be proud.</td>', 'The perfect resting spot. I love how this radiates light. Shez would be proud.', '2013-03-31 11:05:54.000000', NULL, 1),
(7010002, 1059866, 63218, '<td valign="top">Amazing. Complex &amp; simple at the same time. The colors are great together, too.</td>', 'Amazing. Complex & simple at the same time. The colors are great together, too.', '2013-03-31 11:07:09.000000', NULL, 1),
(7010003, 1059702, 100831, '<td valign="top">I think this is wonderful... a tribute to how she made the most out of every little thing. It sparkles and shines, like I can imagine she did. Great thinking.</td>', 'I think this is wonderful... a tribute to how she made the most out of every little thing. It sparkles and shines, like I can imagine she did. Great thinking.', '2013-03-31 11:07:27.000000', NULL, 1),
(7010004, 1060140, 63218, '<td valign="top">Wow that is a most beautiful rose!</td>', 'Wow that is a most beautiful rose!', '2013-03-31 11:10:33.000000', NULL, 1),
(7010006, 1060364, 63218, '<td valign="top">Emotive &amp; yet contemplative. Good work!</td>', 'Emotive & yet contemplative. Good work!', '2013-03-31 11:13:35.000000', NULL, 1),
(7010007, 1060035, 159528, '<td valign="top">Excellent tribute!!!.</td>', 'Excellent tribute!!!.', '2013-03-31 11:14:25.000000', NULL, 1),
(7010019, 1060334, 63218, '<td valign="top">.0</td>', '.0', '2013-03-31 11:38:14.000000', NULL, 1),
(7010084, 1059802, 94265, '<td valign="top">Mournful, hopeless and lonely, yet beautiful and leading off into the distance. It speaks of Shez. Good work.</td>', 'Mournful, hopeless and lonely, yet beautiful and leading off into the distance. It speaks of Shez. Good work.', '2013-03-31 13:35:07.000000', NULL, 1),
(7010090, 1060305, 94265, '<td valign="top">How sweet. :-)</td>', 'How sweet. :-)', '2013-03-31 13:45:24.000000', NULL, 1),
(7010091, 1058320, 94265, '<td valign="top">All that lives, lives forever. Only the shell, the perishable passes away. The spirit is without end. :-)</td>', 'All that lives, lives forever. Only the shell, the perishable passes away. The spirit is without end. :-)', '2013-03-31 13:47:05.000000', NULL, 1),
(7010092, 1060115, 94265, '<td valign="top">Lovely sentiment.</td>', 'Lovely sentiment.', '2013-03-31 13:48:31.000000', NULL, 1),
(7010095, 1059914, 94265, '<td valign="top">Great job, Shez would''ve surely appreciated this style!</td>', 'Great job, Shez would''ve surely appreciated this style!', '2013-03-31 14:04:32.000000', NULL, 1),
(7010096, 1060241, 94265, '<td valign="top">I''m not even religious and I find that little verse very moving, how beautiful; did you come up with it yourself or is it from something? Lovely pink and lilac hues in this shot too, one of my favourites.</td>', 'I''m not even religious and I find that little verse very moving, how beautiful; did you come up with it yourself or is it from something? Lovely pink and lilac hues in this shot too, one of my favourites.', '2013-03-31 14:04:40.000000', NULL, 1),
(7010097, 1058639, 94265, '<td valign="top">This is lovely and a sweet little message, love the soft glowing pinks.</td>', 'This is lovely and a sweet little message, love the soft glowing pinks.', '2013-03-31 14:05:16.000000', NULL, 1),
(7010099, 1059736, 94265, '<td valign="top">Great bokeh and crisp detail where it matters, on the rich colour Shez loved so much!</td>', 'Great bokeh and crisp detail where it matters, on the rich colour Shez loved so much!', '2013-03-31 14:05:54.000000', NULL, 1),
(7010100, 1059471, 94265, '<td valign="top">Great shot overall and a nice message.</td>', 'Great shot overall and a nice message.', '2013-03-31 14:06:30.000000', NULL, 1),
(7010101, 1060364, 94265, '<td valign="top">Delicate and very beautiful.</td>', 'Delicate and very beautiful.', '2013-03-31 14:06:47.000000', NULL, 1),
(7010102, 1058712, 94265, '<td valign="top">I love how the petals look like they''re curling in to each other, comforting each other now that they''ve lost someone who loved their colour so much. Great job.</td>', 'I love how the petals look like they''re curling in to each other, comforting each other now that they''ve lost someone who loved their colour so much. Great job.', '2013-03-31 14:07:25.000000', NULL, 1),
(7010103, 1059915, 94265, '<td valign="top">Love the colourful simplicity.</td>', 'Love the colourful simplicity.', '2013-03-31 14:07:45.000000', NULL, 1),
(7010104, 1058859, 94265, '<td valign="top">Fantastic light, colour and shapes, very nice shot.</td>', 'Fantastic light, colour and shapes, very nice shot.', '2013-03-31 14:08:15.000000', NULL, 1),
(7010105, 1059985, 94265, '<td valign="top">Great vibrant capture!</td>', 'Great vibrant capture!', '2013-03-31 14:08:43.000000', NULL, 1),
(7010106, 1060334, 94265, '<td valign="top">Very pretty tones.</td>', 'Very pretty tones.', '2013-03-31 14:08:53.000000', NULL, 1),
(7010108, 1058615, 94265, '<td valign="top">I love how the rich tones of green fill the frame, very nice.</td>', 'I love how the rich tones of green fill the frame, very nice.', '2013-03-31 14:15:04.000000', NULL, 1),
(7010111, 1058763, 94265, '<td valign="top">Simple and pretty, nice light, good job.</td>', 'Simple and pretty, nice light, good job.', '2013-03-31 14:15:25.000000', NULL, 1),
(7010113, 1059946, 94265, '<td valign="top">I love the straight to the point message and focusing on those lovely pink petals, I think Shez would''ve liked this.</td>', 'I love the straight to the point message and focusing on those lovely pink petals, I think Shez would''ve liked this.', '2013-03-31 14:16:13.000000', NULL, 1),
(7010115, 1060283, 94265, '<td valign="top">Lovely rich colours.</td>', 'Lovely rich colours.', '2013-03-31 14:16:46.000000', NULL, 1),
(7010116, 1059609, 94265, '<td valign="top">I like this idea; Shez has left her seat empty but she''s gone somewhere colourful and lovely, the seat will never be filled. Great job.</td>', 'I like this idea; Shez has left her seat empty but she''s gone somewhere colourful and lovely, the seat will never be filled. Great job.', '2013-03-31 14:17:39.000000', NULL, 1),
(7010117, 1060059, 94265, '<td valign="top">Very pretty image.</td>', 'Very pretty image.', '2013-03-31 14:17:52.000000', NULL, 1),
(7010118, 1060162, 94265, '<td valign="top">Very fitting words, nice background colour, lovely clear shot.</td>', 'Very fitting words, nice background colour, lovely clear shot.', '2013-03-31 14:18:18.000000', NULL, 1),
(7010119, 1060024, 94265, '<td valign="top">Love the quote!</td>', 'Love the quote!', '2013-03-31 14:18:30.000000', NULL, 1),
(7010120, 1059082, 94265, '<td valign="top">This idea really made me smile.</td>', 'This idea really made me smile.', '2013-03-31 14:18:44.000000', NULL, 1),
(7010121, 1060362, 94265, '<td valign="top">Lovely myriad of colour and bokeh here, lush on the eyes.</td>', 'Lovely myriad of colour and bokeh here, lush on the eyes.', '2013-03-31 14:19:13.000000', NULL, 1),
(7010122, 1057859, 94265, '<td valign="top">Simple message but sweet, a powerful mix of power/strength and softness, like Shez.</td>', 'Simple message but sweet, a powerful mix of power/strength and softness, like Shez.', '2013-03-31 14:19:56.000000', NULL, 1),
(7010123, 1060298, 94265, '<td valign="top">Very pretty flowers, nice detail on that central one.</td>', 'Very pretty flowers, nice detail on that central one.', '2013-03-31 14:20:38.000000', NULL, 1),
(7010124, 1059797, 94265, '<td valign="top">Beautiful rich colour!</td>', 'Beautiful rich colour!', '2013-03-31 14:21:47.000000', NULL, 1),
(7010125, 1058450, 94265, '<td valign="top">This is really pretty, soft and sweet. Love the perspective, the flowers appear small and close to the ground yet proud and happy, just like feisty little Shez!</td>', 'This is really pretty, soft and sweet. Love the perspective, the flowers appear small and close to the ground yet proud and happy, just like feisty little Shez!', '2013-03-31 14:23:05.000000', NULL, 1),
(7010126, 1058908, 94265, '<td valign="top">I like the little pebbles background. I like the thin red outline of the shot, works really well with the same outline on the leaves.</td>', 'I like the little pebbles background. I like the thin red outline of the shot, works really well with the same outline on the leaves.', '2013-03-31 14:23:56.000000', NULL, 1),
(7010127, 1059714, 94265, '<td valign="top">This verse made me sad, it''s very poignant and pretty. Works well with the little flower covered in dew, like even the flower is crying.</td>', 'This verse made me sad, it''s very poignant and pretty. Works well with the little flower covered in dew, like even the flower is crying.', '2013-03-31 14:24:45.000000', NULL, 1),
(7010128, 1060333, 94265, '<td valign="top">The bokeh is really colourful and pretty here.</td>', 'The bokeh is really colourful and pretty here.', '2013-03-31 14:24:59.000000', NULL, 1),
(7010129, 1060178, 94265, '<td valign="top">I''m liking these fill-the-frame shots, nothing to distract from the lovely plants and flowers that Shez loved. Nice job.</td>', 'I''m liking these fill-the-frame shots, nothing to distract from the lovely plants and flowers that Shez loved. Nice job.', '2013-03-31 14:25:54.000000', NULL, 1),
(7010131, 1059608, 94265, '<td valign="top">Always good to remember. :-)</td>', 'Always good to remember. :-)', '2013-03-31 14:28:43.000000', NULL, 1),
(7010132, 1060244, 94265, '<td valign="top">At first glance I was overwhelmed by the orange, then I realised I like the rich bloom of colour and Shez would''ve too. :-) Very pretty and delicate.</td>', 'At first glance I was overwhelmed by the orange, then I realised I like the rich bloom of colour and Shez would''ve too. :-) Very pretty and delicate.', '2013-03-31 14:29:40.000000', NULL, 1),
(7010133, 1059109, 94265, '<td valign="top">Pretty flowers, I like that the border isn''t block-coloured too and that it changes with the brightness of the photo.</td>', 'Pretty flowers, I like that the border isn''t block-coloured too and that it changes with the brightness of the photo.', '2013-03-31 14:30:42.000000', NULL, 1),
(7010134, 1058613, 94265, '<td valign="top">She sure did. :-) Very pretty image.</td>', 'She sure did. :-) Very pretty image.', '2013-03-31 14:30:59.000000', NULL, 1),
(7010135, 1058872, 94265, '<td valign="top">Haha, Shez surely would''ve had a chuckle at this, well done. The most delicious of the tributes!</td>', 'Haha, Shez surely would''ve had a chuckle at this, well done. The most delicious of the tributes!', '2013-03-31 14:31:34.000000', NULL, 1),
(7010136, 1060126, 94265, '<td valign="top">Nice clear details overall, great complimentary colours, nice little pop of green.</td>', 'Nice clear details overall, great complimentary colours, nice little pop of green.', '2013-03-31 14:32:14.000000', NULL, 1);
INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(7010137, 1060140, 94265, '<td valign="top">Very pretty details and hues on this one.</td>', 'Very pretty details and hues on this one.', '2013-03-31 14:32:31.000000', NULL, 1),
(7010138, 1059441, 94265, '<td valign="top">So small and yet so lovely, a very sweet tribute to a lady of the same.</td>', 'So small and yet so lovely, a very sweet tribute to a lady of the same.', '2013-03-31 14:33:21.000000', NULL, 1),
(7010139, 1059876, 94265, '<td valign="top">Beautiful flower, I like the title too.</td>', 'Beautiful flower, I like the title too.', '2013-03-31 14:34:05.000000', NULL, 1),
(7010141, 1060201, 94265, '<td valign="top">The softness of this is very sweet, with just a gentle touch of lovely pink.</td>', 'The softness of this is very sweet, with just a gentle touch of lovely pink.', '2013-03-31 14:34:38.000000', NULL, 1),
(7010142, 1060340, 94265, '<td valign="top">''At the Forefront of our Thoughts'' is the first thing that came to mind when I saw this, a very nice tribute.</td>', '''At the Forefront of our Thoughts'' is the first thing that came to mind when I saw this, a very nice tribute.', '2013-03-31 14:35:31.000000', NULL, 1),
(7010145, 1060128, 94265, '<td valign="top">A lovely image, it looks very warm and the distance is beautiful, a very fitting tribute.</td>', 'A lovely image, it looks very warm and the distance is beautiful, a very fitting tribute.', '2013-03-31 14:36:18.000000', NULL, 1),
(7010147, 1059998, 94265, '<td valign="top">Simple and beautiful, great contrast here of a vibrant cheerful flower and the sad-looking little pollen parts. A good mixture of thoughts, as everyone feels when they lose someone.</td>', 'Simple and beautiful, great contrast here of a vibrant cheerful flower and the sad-looking little pollen parts. A good mixture of thoughts, as everyone feels when they lose someone.', '2013-03-31 14:38:20.000000', NULL, 1),
(7010149, 1059836, 94265, '<td valign="top">Shez would''ve appreciated the nice colour range.</td>', 'Shez would''ve appreciated the nice colour range.', '2013-03-31 14:39:18.000000', NULL, 1),
(7010150, 1060034, 94265, '<td valign="top">A very moving tribute, very appropriate, well done.<br/><br/><i>Message edited by author 2013-04-02 09:15:21.</i></td>', 'A very moving tribute, very appropriate, well done.', '2013-03-31 14:39:55.000000', '2013-04-02 10:15:21.000000', 1),
(7010151, 1058502, 94265, '<td valign="top">Soft, pretty and fitting. :-)</td>', 'Soft, pretty and fitting. :-)', '2013-03-31 14:40:10.000000', NULL, 1),
(7010152, 1060032, 94265, '<td valign="top">Nice details, the pinks and mustardy yellows make a good combination.</td>', 'Nice details, the pinks and mustardy yellows make a good combination.', '2013-03-31 14:41:02.000000', NULL, 1),
(7010153, 1059830, 94265, '<td valign="top">What a pretty, soft shade of red.</td>', 'What a pretty, soft shade of red.', '2013-03-31 14:41:42.000000', NULL, 1),
(7010154, 1060163, 94265, '<td valign="top">Lovely verse and lovely little splashes of purple.</td>', 'Lovely verse and lovely little splashes of purple.', '2013-03-31 14:42:13.000000', NULL, 1),
(7010155, 1060369, 94265, '<td valign="top">This is cool and Shez would''ve really liked this, I''m sure; nice clear details and a great little spectrum of colour.</td>', 'This is cool and Shez would''ve really liked this, I''m sure; nice clear details and a great little spectrum of colour.', '2013-03-31 14:42:53.000000', NULL, 1),
(7010156, 1060205, 94265, '<td valign="top">These petals almost look like little apple slices, how cool!</td>', 'These petals almost look like little apple slices, how cool!', '2013-03-31 14:43:15.000000', NULL, 1),
(7010157, 1060135, 94265, '<td valign="top">They look so sad yet they''re still lovely, very fitting for the challenge.</td>', 'They look so sad yet they''re still lovely, very fitting for the challenge.', '2013-03-31 14:43:52.000000', NULL, 1),
(7010158, 1059807, 94265, '<td valign="top">I feel there must''ve been a lovely shade of colour on this flower but the monochrome portrays the sadness her friends are feeling; life is not always about experiencing the colour, sometimes it''s the bleak darkness. I appreciate this shot for that reason. Plus, the monochrome helps us focus on the little details of the stem and the lines of the petals.</td>', 'I feel there must''ve been a lovely shade of colour on this flower but the monochrome portrays the sadness her friends are feeling; life is not always about experiencing the colour, sometimes it''s the bleak darkness. I appreciate this shot for that reason. Plus, the monochrome helps us focus on the little details of the stem and the lines of the petals.', '2013-03-31 14:46:53.000000', NULL, 1),
(7010159, 1060322, 94265, '<td valign="top">This is made much more sad by the inclusion of a child in the shot. Maybe a bit too sombre for me personally but a good effort.</td>', 'This is made much more sad by the inclusion of a child in the shot. Maybe a bit too sombre for me personally but a good effort.', '2013-03-31 14:48:02.000000', NULL, 1),
(7010161, 1059203, 94265, '<td valign="top">Me too. :-) Good to see a different take on the challenge.</td>', 'Me too. :-) Good to see a different take on the challenge.', '2013-03-31 14:49:26.000000', NULL, 1),
(7010162, 1060359, 94265, '<td valign="top">Pretty colour mix.</td>', 'Pretty colour mix.', '2013-03-31 14:49:35.000000', NULL, 1),
(7010163, 1060149, 94265, '<td valign="top">A wee bit dark but the rich colour is clearly there, which is the important thing for Shez.</td>', 'A wee bit dark but the rich colour is clearly there, which is the important thing for Shez.', '2013-03-31 14:50:58.000000', NULL, 1),
(7010165, 1059629, 94265, '<td valign="top">I''m not sure about the title as it suggests her passing was not peaceful, that it was more of a battle; however, sometimes life is hard and we must face the reality of that. The birds are pretty, kinda looks painting-like.</td>', 'I''m not sure about the title as it suggests her passing was not peaceful, that it was more of a battle; however, sometimes life is hard and we must face the reality of that. The birds are pretty, kinda looks painting-like.', '2013-03-31 14:53:22.000000', NULL, 1),
(7010166, 1060332, 94265, '<td valign="top">A little soft perhaps but the background colour is nice. Sweet sentiment in the title.</td>', 'A little soft perhaps but the background colour is nice. Sweet sentiment in the title.', '2013-03-31 14:54:27.000000', NULL, 1),
(7010167, 1060350, 68504, '<td valign="top">great sculptural effect.</td>', 'great sculptural effect.', '2013-03-31 14:55:10.000000', NULL, 1),
(7010168, 1057926, 68504, '<td valign="top">fascinating revocation.</td>', 'fascinating revocation.', '2013-03-31 14:55:46.000000', NULL, 1),
(7010169, 1060167, 94265, '<td valign="top">This is very sad and ethereal, the kind of shot I normally wouldn''t really like, yet the faint sepia-look and that simple hand reaching out is actually quite moving in this context.</td>', 'This is very sad and ethereal, the kind of shot I normally wouldn''t really like, yet the faint sepia-look and that simple hand reaching out is actually quite moving in this context.', '2013-03-31 14:55:48.000000', NULL, 1),
(7010170, 1060324, 68504, '<td valign="top">fine distillation of colours.</td>', 'fine distillation of colours.', '2013-03-31 14:56:15.000000', NULL, 1),
(7010171, 1059364, 94265, '<td valign="top">Vibrant range of colours.</td>', 'Vibrant range of colours.', '2013-03-31 14:56:20.000000', NULL, 1),
(7010173, 1057859, 68504, '<td valign="top">love the drama in muted tones.</td>', 'love the drama in muted tones.', '2013-03-31 14:56:51.000000', NULL, 1),
(7010174, 1059670, 94265, '<td valign="top">Too soon indeed. The cold look of the the blue hues and the snow definitely fits our feelings.</td>', 'Too soon indeed. The cold look of the the blue hues and the snow definitely fits our feelings.', '2013-03-31 14:57:36.000000', NULL, 1),
(7010175, 1058751, 68504, '<td valign="top">distillation of vegetable kingdom.</td>', 'distillation of vegetable kingdom.', '2013-03-31 14:58:37.000000', NULL, 1),
(7010177, 1058859, 68504, '<td valign="top">splendid sherisma.</td>', 'splendid sherisma.', '2013-03-31 14:59:30.000000', NULL, 1),
(7010178, 1060201, 68504, '<td valign="top">yes.</td>', 'yes.', '2013-03-31 14:59:48.000000', NULL, 1),
(7010179, 1059657, 94265, '<td valign="top">I think Shez would appreciate the inspirational feeling of this.</td>', 'I think Shez would appreciate the inspirational feeling of this.', '2013-03-31 15:01:01.000000', NULL, 1),
(7010180, 1060300, 68504, '<td valign="top">what a wonderful vinous tumble. backstage. original.</td>', 'what a wonderful vinous tumble. backstage. original.', '2013-03-31 15:01:55.000000', NULL, 1),
